1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * On create, reduces the telephone to its digits and requires exactly ten of them.
9	 * Mutates the built {@link Owner} in place so later steps store and return the 10-digit value.
10	 */
11	public class NormalizeOwnerTelephone {
12	
13	    public void service(@Val Owner owner) throws InvalidTelephoneException {
14	        String digits = owner.getTelephone() == null ? "" : owner.getTelephone().replaceAll("\\D", "");
15	        if (digits.length() != 10) {
16	            throw new InvalidTelephoneException("Telephone must contain exactly 10 digits");
17	        }
18	        owner.setTelephone(digits);
19	    }
20	}
